// FE: serie "La mochila del muñequito". Cada carga se entrega a Dios en la palabra "entrego".
import React from 'react';
import {useS, en, fin, ventana, Destello, AbsoluteFill, interpolate, clamp, DUR} from './kit';

const W = 1080;
const H = 1920;

const CAMINO = en('aqui');
const CIMA = en('esa');
const CUENTA = en('cuenta');
const LLAMADA = en('llamada');
const MIEDO = en('miedo');
const E1 = en('entrego', 1);
const E2 = en('entrego', 2);
const E3 = en('entrego', 3);
const PIEDRAS = en('piedras');
const DELANTE = en('delante');
const TEMAS = en('temas');
const LIVIANO = en('liviano');
const PERSONA = en('persona');
const BRAZOS = en('brazos');
const NOMBRE = en('nombre');
const AMEN = en('amen');

const Mochila: React.FC<{peso: number}> = ({peso}) => (
  <g transform={`translate(-112,-56) scale(${peso * 0.74})`}>
    <ellipse cx={0} cy={0} rx={120} ry={132} fill="url(#saco)" stroke="#5a3519" strokeWidth={7} />
    <path d="M-92 -58 Q0 -16 92 -58" fill="none" stroke="#5a3519" strokeWidth={9} />
    <rect x={-46} y={8} width={92} height={74} rx={18} fill="#a8703c" stroke="#5a3519" strokeWidth={6} />
    <circle cx={0} cy={-34} r={11} fill="#f0c674" />
    <ellipse cx={-48} cy={-76} rx={34} ry={14} fill="#f6d6a8" opacity={0.3} />
  </g>
);

type MunecoP = {x: number; y: number; e?: number; s: number; pasos?: number; peso?: number; ojos?: number; orar?: number; feliz?: number; aplasta?: number; desfase?: number; ropa?: string};

// Protagonista de la serie: reutilizado en todos los sitios, con bufanda dorada.
const Muneco: React.FC<MunecoP> = ({x, y, e = 1, s, pasos = 0, peso = 0, ojos = 1, orar = 0, feliz = 0.5, aplasta = 0, desfase = 0, ropa = 'sudadera'}) => {
  const t = s + desfase;
  const brinco = -pasos * Math.abs(Math.sin(t * 4.6)) * 14;
  const respira = Math.sin(t * 2.1) * 0.012;
  const pierna = Math.sin(t * 4.6) * 26 * pasos;
  const brazo = Math.sin(t * 4.6) * 30 * pasos;
  const parpadeo = (t * 0.27) % 1 > 0.975 ? 0.08 : 1;
  const ry = 30 * ojos * parpadeo + 1.5;
  const largo = 120 - orar * 70;
  return (
    <g transform={`translate(${x},${y + brinco + orar * 62}) scale(${e * (1 + respira)},${e * (1 - respira - aplasta)})`}>
      <ellipse cx={0} cy={198 - orar * 62} rx={190} ry={24} fill="#1c1208" opacity={0.28} />
      {[-1, 1].map((l) => (
        <g key={l} transform={`translate(${l * 48},82) rotate(${pierna * l})`}>
          <rect x={-29} y={0} width={58} height={largo} rx={26} fill="#3f5472" />
          <ellipse cx={l * 8} cy={largo} rx={44} ry={26} fill="#f2ead8" stroke="#bda98b" strokeWidth={4} />
        </g>
      ))}
      {peso > 0.02 ? <Mochila peso={peso} /> : null}
      <rect x={-108} y={-84} width={216} height={190} rx={84} fill={`url(#${ropa})`} />
      {peso > 0.02 ? <path d="M-70 -66 Q-82 10 -66 76 M70 -66 Q82 10 66 76" fill="none" stroke="#5a3519" strokeWidth={15} strokeLinecap="round" /> : null}
      {orar < 0.5
        ? [-1, 1].map((l) => (
            <g key={l} opacity={1 - orar * 2} transform={`translate(${l * 104},-46) rotate(${l * 10 + brazo * l})`}>
              <rect x={-25} y={0} width={50} height={126} rx={24} fill={`url(#${ropa})`} />
              <circle cy={130} r={27} fill="url(#piel)" />
            </g>
          ))
        : null}
      <g transform={`translate(0,-184) rotate(${Math.sin(t * 1.1) * 1.8}) rotate(${orar * 4})`}>
        <circle cx={-132} cy={8} r={28} fill="#c98e60" />
        <circle cx={132} cy={8} r={28} fill="#c98e60" />
        <circle r={136} fill="url(#piel)" />
        <path d="M-136 -6 Q-128 -146 0 -148 Q128 -146 136 -6 Q84 -86 26 -74 Q-58 -60 -136 -6 Z" fill="#2e1c14" />
        <path d={`M-84 ${-20 + (1 - feliz) * -7} Q-54 ${-30 - (1 - feliz) * 2} -24 ${-22 + (1 - feliz) * 12}`} fill="none" stroke="#2e1c14" strokeWidth={8} strokeLinecap="round" />
        <path d={`M24 ${-22 + (1 - feliz) * 12} Q54 ${-30 - (1 - feliz) * 2} 84 ${-20 + (1 - feliz) * -7}`} fill="none" stroke="#2e1c14" strokeWidth={8} strokeLinecap="round" />
        <ellipse cx={-54} cy={26} rx={25} ry={ry} fill="#20140f" />
        <ellipse cx={54} cy={26} rx={25} ry={ry} fill="#20140f" />
        {ojos > 0.25 ? <circle cx={-45} cy={13} r={8} fill="#fff" /> : null}
        {ojos > 0.25 ? <circle cx={63} cy={13} r={8} fill="#fff" /> : null}
        <ellipse cx={-92} cy={68} rx={28} ry={17} fill="#e8796a" opacity={0.25 + feliz * 0.4} />
        <ellipse cx={92} cy={68} rx={28} ry={17} fill="#e8796a" opacity={0.25 + feliz * 0.4} />
        <path d={`M-34 ${94 - (feliz - 0.5) * 8} Q0 ${94 + (feliz - 0.5) * 50} 34 ${94 - (feliz - 0.5) * 8}`} fill="none" stroke="#6d3a26" strokeWidth={8} strokeLinecap="round" />
      </g>
      <path d="M-104 -72 Q0 -30 104 -72 L96 -36 Q0 4 -96 -36 Z" fill="#f0b63e" stroke="#c98a22" strokeWidth={3} />
      <rect x={38} y={-34} width={46} height={92} rx={14} fill="#f0b63e" stroke="#c98a22" strokeWidth={3} />
      {orar > 0.01 ? (
        <g opacity={orar} transform={`translate(0,${84 - orar * 92})`}>
          <rect x={-58} y={-20} width={50} height={126} rx={24} fill={`url(#${ropa})`} transform="rotate(16 -33 40)" />
          <rect x={8} y={-20} width={50} height={126} rx={24} fill={`url(#${ropa})`} transform="rotate(-16 33 40)" />
          <ellipse cx={-13} cy={-42} rx={20} ry={36} fill="url(#piel)" />
          <ellipse cx={13} cy={-42} rx={20} ry={36} fill="url(#piel)" />
        </g>
      ) : null}
    </g>
  );
};

