      <path d="M-92 -146 Q-88 -248 0 -246 Q88 -248 92 -146 Q100 -80 72 -60 Q70 -150 0 -176 Q-70 -150 -72 -60 Q-100 -80 -92 -146 Z" fill="#c9924c" />
      <path d="M-46 -136 Q-32 -122 -18 -136 M18 -136 Q32 -122 46 -136" fill="none" stroke="#4a2e1e" strokeWidth={7} strokeLinecap="round" />
