    {[0, 1, 2, 3, 4, 5, 6, 7].map((i) => (
      <rect key={i} x={x - 9} y={y + r * 1.25} width={18} height={r * 1.6} rx={9} fill="#ffe9b0" opacity={0.28} transform={`rotate(${i * 45 + s * 3} ${x} ${y})`} />
    ))}
    <circle cx={x} cy={y} r={r} fill="#fff1c0" />
  </g>
);

const Colina: React.FC<{y: number; alto: number; color: string; despl: number; ancho: number}> = ({y, alto, color, despl, ancho}) => {
  const x0 = -(((despl % ancho) + ancho) % ancho);
  return (
    <g>
      {[0, 1, 2, 3].map((i) => (
        <path key={i} d={`M${x0 + i * ancho} ${y + alto} Q${x0 + i * ancho + ancho / 2} ${y - alto} ${x0 + (i + 1) * ancho} ${y + alto} Z`} fill={color} />
      ))}
      <rect y={y + alto - 1} width={W} height={H} fill={color} />
    </g>
  );
};

const Sendero: React.FC<{s: number; avance: number; dia: number; piedras: number}> = ({s, avance, dia, piedras}) => (
