const Ave: React.FC<{k: number}> = ({k}) => <path d={`M-60 ${-20 * k} Q-26 ${-56 * k} 0 0 Q26 ${-56 * k} 60 ${-20 * k} Q24 ${-8 * k} 0 24 Q-24 ${-8 * k} -60 ${-20 * k} Z`} fill="#fff5cf" stroke="#ffd98a" strokeWidth={4} />;

