// Sale de la mochila, flota y en "entrego" sube hacia la luz convertido en ave.
const Carga: React.FC<{s: number; t0: number; t1: number; hx: number; hy: number; children: React.ReactNode}> = ({s, t0, t1, hx, hy, children}) => {
  const k = interpolate(s, [t0, t0 + 0.55], [0, 1], {...clamp});
  const sube = interpolate(s, [t1, t1 + 1.5], [0, 1], {...clamp});
  if (k <= 0 || sube >= 1) return null;
  const x = interpolate(k, [0, 1], [260, hx]) + (800 - hx) * sube * sube;
  const y = interpolate(k, [0, 1], [1070, hy]) + Math.sin(s * 2) * 9 + (640 - hy) * sube;
  const obj = 1 - interpolate(sube, [0, 0.3], [0, 1], {...clamp});
  const ave = interpolate(sube, [0.1, 0.35, 0.85, 1], [0, 1, 1, 0], {...clamp});
  return (
    <g transform={`translate(${x},${y}) scale(${0.45 + k * 0.75})`}>
      <g opacity={obj}>{children}</g>
      <g opacity={ave} transform="scale(1.5)"><Ave k={0.65 + Math.sin(s * 12) * 0.35} /></g>
    </g>
  );
};

