export const Escena: React.FC = () => {
  const {s, lin, spr} = useS();
  const cuarto = s < CAMINO;
  const cima = s >= CIMA;
  const peso1 = interpolate(s, [E1, E1 + 0.7, E2, E2 + 0.7, E3, E3 + 0.7, LIVIANO - 0.2, LIVIANO + 0.1], [1.7, 1.35, 1.35, 1, 1, 0.68, 0.68, 0], {...clamp});
  const pesoCuarto = interpolate(s, [en('cargando') - 0.2, en('cargando') + 0.4, en('mochila') - 0.2, en('mochila') + 0.4], [1.3, 1.5, 1.5, 1.7], {...clamp});
  const entra = lin(CAMINO, CAMINO + 0.35, 0.88, 1);
  const luzCuarto = lin(en('sabado') - 0.8, en('mochila'), 0.05, 1);
  const zoomCuarto = interpolate(s, [0, en('mochila'), CAMINO], [1.02, 1.1, 1.3], {...clamp});
  const avance = Math.min(s, TEMAS) * 170;
  const dia = lin(CAMINO, CIMA, 0, 1);
  const zoomSenda = interpolate(s, [CAMINO, PIEDRAS, DELANTE, TEMAS, LIVIANO, CIMA], [1, 1.09, 1.02, 1, 1.08, 1.03], {...clamp});
  const luzGuia = lin(DELANTE - 0.2, DELANTE + 0.6, 0, 1) * (1 - lin(TEMAS - 0.2, TEMAS + 0.5, 0, 1));
  const baja = lin(TEMAS - 0.2, TEMAS + 1.6, 0, 1);
  const angelY = interpolate(baja, [0, 1], [-520, 900]);
  const arrodilla = lin(TEMAS - 0.4, TEMAS + 0.2, 0, 1) * (1 - lin(LIVIANO, LIVIANO + 0.3, 0, 1));
  const llevar = lin(LIVIANO - 0.2, LIVIANO + 0.8, 0, 1);
  const zoomCima = interpolate(s, [CIMA, BRAZOS, NOMBRE, Math.max(AMEN + 1, DUR)], [1, 1.04, 1.3, 1.46], {...clamp});
  const orar = lin(NOMBRE - 0.2, NOMBRE + 0.5, 0, 1);
  const salto = Math.abs(Math.sin((s - LIVIANO) * 6.2)) * 58 * ventana(s, LIVIANO + 0.2, LIVIANO + 1.2, 0.2);
  const otra = spr(PERSONA - 0.1, 15, 90);
  const abrazo = lin(BRAZOS - 0.2, BRAZOS + 0.8, 0, 1);

  return (
    <AbsoluteFill style={{background: '#2a2438'}}>
      <svg width={W} height={H} viewBox={`0 0 ${W} ${H}`} style={{position: 'absolute', left: 0, top: 0}}>
        <Defs />
        {cuarto ? (
          <g transform={`translate(${W / 2},1180) scale(${zoomCuarto}) translate(${-W / 2},-1180)`}>
            <Cuarto s={s} luz={luzCuarto} />
            <Muneco x={540} y={1040} e={1.45} s={s} peso={pesoCuarto} ojos={lin(0, 1.1, 0.25, 1.1)} feliz={0.1 + luzCuarto * 0.2} aplasta={0.05 + Math.sin(s * 1.7) * 0.012} />
          </g>
        ) : null}
        {!cuarto && !cima ? (
          <g transform={`translate(${W / 2},1180) scale(${zoomSenda * entra}) translate(${-W / 2},-1180)`}>
            <Sendero s={s} avance={avance} dia={dia} piedras={lin(PIEDRAS - 0.2, PIEDRAS + 0.4, 0, 1)} />
            <Carga s={s} t0={CUENTA - 0.45} t1={E1} hx={690} hy={830}><Papel /></Carga>
            <Carga s={s} t0={LLAMADA - 0.45} t1={E2} hx={700} hy={820}><Telefono s={s} /></Carga>
            <Carga s={s} t0={MIEDO - 0.45} t1={E3} hx={700} hy={790}><Nube s={s} /></Carga>
            {luzGuia > 0 ? (
              <g opacity={luzGuia} transform={`translate(${910 + Math.sin(s * 0.9) * 24},${1186 + Math.sin(s * 1.5) * 12})`}>
                <circle r={250 + Math.sin(s * 2) * 12} fill="url(#brillo)" />
                <circle r={46} fill="#fffbe6" />
              </g>
            ) : null}
            {baja > 0 ? <Angel x={720} y={angelY} e={1.05} s={s} /> : null}
            {llevar > 0 && llevar < 1 ? (
              <g opacity={1 - llevar * llevar} transform={`translate(${interpolate(llevar, [0, 1], [300, 470])},${interpolate(llevar, [0, 1], [1130, 960])}) scale(${0.8 - llevar * 0.2})`}>
                <Mochila peso={1} />
              </g>
            ) : null}
            <Muneco x={400} y={1186 - salto} e={1.25} s={s} pasos={1 - lin(TEMAS - 0.4, TEMAS, 0, 1)} peso={peso1} ojos={1 - arrodilla * 0.85} orar={arrodilla} feliz={1 - (peso1 / 1.7) * 0.75} aplasta={peso1 * 0.022} />
          </g>
        ) : null}
        {cima ? (
          <g transform={`translate(420,1120) scale(${zoomCima}) translate(-420,-1120)`}>
            <Cima s={s} luz={abrazo} />
            <Angel x={640} y={740} e={1} s={s} o={0.55 + abrazo * 0.45} />
            <g opacity={otra}>
              <Muneco x={830 + (1 - otra) * 300} y={1236} e={0.92} s={s} desfase={1.7} ropa="sudadera2" feliz={0.45 + abrazo * 0.5} ojos={1 - abrazo * 0.75} orar={orar} />
            </g>
            <Muneco x={390} y={1216} e={1.2} s={s} feliz={1} ojos={interpolate(orar, [0, 1], [1, 0.1])} orar={orar} />
          </g>
        ) : null}
      </svg>
      <Destello t0={E1} fuerza={0.18} />
      <Destello t0={E2} fuerza={0.18} />
      <Destello t0={E3} fuerza={0.2} />
      <Destello t0={fin('temas')} fuerza={0.24} />
      <Destello t0={fin('liviano')} fuerza={0.2} />
      <AbsoluteFill style={{background: 'radial-gradient(circle at 50% 56%, transparent 56%, rgba(40,20,14,0.34) 100%)'}} />
    </AbsoluteFill>
  );
};
